"use strict";(self.webpackChunkdoc_crossplaycore=self.webpackChunkdoc_crossplaycore||[]).push([[3361],{4782:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"1-2-0","metadata":{"permalink":"/changelog/1-2-0","source":"@site/changelog/2026-11-26-1-2-0/index.md","title":"CrossplayCore 1.2.0","description":"CHANGED","date":"2026-11-26T22:09:30.000Z","tags":[],"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"CrossplayCore 1.2.0","slug":"1-2-0","date":"2026-11-26T22:09:30"},"unlisted":false,"nextItem":{"title":"CrossplayCore 1.1.0","permalink":"/changelog/1-1-0"}},"content":"## CHANGED\\n\\n- Enabled Online Subsystem Steam and Steam Sockets as plugin dependencies on Windows, Linux, and macOS.\\n- Lobby update operations now report failures returned by Steam or Epic Online Services (EOS) to the caller.\\n- Added a Crossplay Blueprint example to the sample project.\\n\\n## FIXED\\n\\n- Fixed a race condition when destroying a session while a create, join, or update operation was still in progress. Session destruction now waits for the active operation to finish.\\n- Fixed pending login retries continuing after logout.\\n- Improved how Steam and EOS callbacks handle login, lobby membership, and session state changes."},{"id":"1-1-0","metadata":{"permalink":"/changelog/1-1-0","source":"@site/changelog/2026-11-26-1-1-0/index.md","title":"CrossplayCore 1.1.0","description":"ADDED","date":"2026-11-26T00:00:00.000Z","tags":[],"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"CrossplayCore 1.1.0","slug":"1-1-0"},"unlisted":false,"prevItem":{"title":"CrossplayCore 1.2.0","permalink":"/changelog/1-2-0"}},"content":"## ADDED\\n\\n- Added stats, leaderboards, and achievement progress APIs for Steam and EOS, available through Blueprint and the Crossplay Online Subsystem.\\n- Added Quick Match, which looks for a lobby to join and creates one if no suitable lobby is available.\\n- Added platform restrictions for lobbies and an option to prevent players from joining a match in progress.\\n- Added lobby management and social APIs for updating lobby settings, kicking players, sending lobby chat messages, ending matches, and accessing avatars and recent players.\\n- Added EOS player reports, sanctions checks, and friend requests. Configured sanctions can block lobby creation, joining, and Quick Match.\\n\\n## FIXED\\n\\n- Fixed an issue where two players using Quick Match at the same time could create separate lobbies and remain split.\\n- Lobby creation, joining, and Quick Match now wait for the initial EOS sanctions check when lobby-blocking sanctions are configured.\\n- Successful lobby settings updates are now reflected immediately in the current lobby.\\n- Logging out now cancels pending login and lobby requests while preserving EOS logins managed by other plugins."}]}}')}}]);